BEGIN;
CREATE SCHEMA IF NOT EXISTS demi AUTHORIZATION demi_owner;
SET LOCAL search_path = demi, public;
SET LOCAL ROLE demi_owner;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY,checksum_sha256 text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS silos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('global','book')),slug text NOT NULL,name text NOT NULL,ordinal integer,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,slug));
CREATE UNIQUE INDEX IF NOT EXISTS one_global_silo_per_project ON silos(project_id) WHERE kind='global';
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,legacy_name text UNIQUE,title text,summary text,status text NOT NULL DEFAULT 'inactive' CHECK(status IN('active','inactive','archived')),predecessor_id uuid REFERENCES sessions(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session_per_project ON sessions(project_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS session_silos(session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,silo_id uuid NOT NULL REFERENCES silos(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('focus','reference')),reason text,source text NOT NULL DEFAULT 'manual' CHECK(source IN('manual','ai-suggested','inherited','imported')),confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(session_id,silo_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_focus_silo_per_session ON session_silos(session_id) WHERE role='focus';
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,legacy_entry_id text UNIQUE,sequence_number bigint NOT NULL,author text NOT NULL,entry_type text,body text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL,source_path text,source_sha256 text,UNIQUE(session_id,sequence_number));
CREATE INDEX IF NOT EXISTS messages_session_created_idx ON messages(session_id,created_at);
CREATE INDEX IF NOT EXISTS messages_search_idx ON messages USING gin(to_tsvector('english',body));
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,silo_id uuid REFERENCES silos(id) ON DELETE SET NULL,kind text NOT NULL,title text NOT NULL,source_path text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,source_path));
CREATE TABLE IF NOT EXISTS document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,version_label text,source_sha256 text NOT NULL,extracted_text text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,imported_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,source_sha256));
CREATE TABLE IF NOT EXISTS document_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_version_id uuid NOT NULL REFERENCES document_versions(id) ON DELETE CASCADE,parent_id uuid REFERENCES document_sections(id) ON DELETE CASCADE,ordinal integer NOT NULL,heading text,body text NOT NULL,locator jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(document_version_id,ordinal));
CREATE INDEX IF NOT EXISTS document_sections_search_idx ON document_sections USING gin(to_tsvector('english',coalesce(heading,'')||' '||body));
CREATE TABLE IF NOT EXISTS entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,home_silo_id uuid REFERENCES silos(id) ON DELETE SET NULL,kind text NOT NULL,canonical_name text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(project_id,kind,canonical_name));
CREATE TABLE IF NOT EXISTS entity_aliases(entity_id uuid NOT NULL REFERENCES entities(id) ON DELETE CASCADE,alias text NOT NULL,PRIMARY KEY(entity_id,alias));
CREATE TABLE IF NOT EXISTS claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,scope_silo_id uuid REFERENCES silos(id) ON DELETE SET NULL,normalized_claim text NOT NULL,adoption_status text NOT NULL DEFAULT 'suggested' CHECK(adoption_status IN('suggested','proposed','canon')),verification_status text NOT NULL DEFAULT 'not_required' CHECK(verification_status IN('not_required','needs_verification','verified','failed','disputed')),disposition text NOT NULL DEFAULT 'active' CHECK(disposition IN('active','rejected','superseded','unresolved')),superseded_by uuid REFERENCES claims(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS claim_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL REFERENCES claims(id) ON DELETE CASCADE,message_id uuid REFERENCES messages(id) ON DELETE SET NULL,document_section_id uuid REFERENCES document_sections(id) ON DELETE SET NULL,evidence_type text NOT NULL CHECK(evidence_type IN('origin','support','objection','milo_confirmation','source','supersession')),excerpt text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(message_id IS NOT NULL OR document_section_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS participant_positions(claim_id uuid NOT NULL REFERENCES claims(id) ON DELETE CASCADE,participant text NOT NULL,position text NOT NULL CHECK(position IN('suggested','agree','agree_with_revisions','disagree','confirmed','withdrawn')),evidence_message_id uuid REFERENCES messages(id) ON DELETE SET NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(claim_id,participant));
CREATE TABLE IF NOT EXISTS verification_checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL REFERENCES claims(id) ON DELETE CASCADE,verifier text NOT NULL,status text NOT NULL CHECK(status IN('verified','failed','disputed','inconclusive')),method text,evidence jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_model_settings(project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,participant text NOT NULL,runtime text NOT NULL,model text,reasoning_effort text,settings jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,participant));
CREATE TABLE IF NOT EXISTS events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid REFERENCES projects(id) ON DELETE CASCADE,event_type text NOT NULL,actor text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS retrieval_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,session_id uuid REFERENCES sessions(id) ON DELETE SET NULL,participant text NOT NULL,focus_silo_id uuid REFERENCES silos(id) ON DELETE SET NULL,query_text text,retrieved_items jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO projects(slug,name) VALUES('demi-project','My Project') ON CONFLICT(slug) DO NOTHING;
INSERT INTO silos(project_id,kind,slug,name) SELECT id,'global','global','Global' FROM projects WHERE slug='demi-project' ON CONFLICT(project_id,slug) DO NOTHING;
RESET ROLE;
GRANT USAGE ON SCHEMA demi TO demi_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA demi TO demi_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA demi TO demi_app;
ALTER DEFAULT PRIVILEGES FOR ROLE demi_owner IN SCHEMA demi GRANT SELECT,INSERT,UPDATE,DELETE ON TABLES TO demi_app;
ALTER DEFAULT PRIVILEGES FOR ROLE demi_owner IN SCHEMA demi GRANT USAGE,SELECT ON SEQUENCES TO demi_app;
COMMIT;
